const results=sources.map(source=>{
  const body=$('Daily · '+source.toUpperCase()).first().json;
  const row=Array.isArray(body.results)?body.results.find(x=>x.source===source):null;
  return {source,status:row?.status??'failed',batchId:typeof row?.batchId==='string'?row.batchId:null};
});
const outcome=$('Daily · ประเมินด้วย VPS AI').first().json;
const assessment={state:typeof outcome.state==='string'?outcome.state:'unavailable',jobId:typeof outcome.jobId==='string'?outcome.jobId:null,reused:outcome.reused===true};
if(results.some(row=>!['completed','duplicate'].includes(row.status))) throw new Error('ANALYTICS_DAILY_INCOMPLETE');
if(!['queued','leased','succeeded','skipped'].includes(assessment.state)) throw new Error('ANALYTICS_ASSESSMENT_INCOMPLETE');
