const missingConfirmed=!exists&&[400,404].includes(Number(response.statusCode))&&!!body.error;
let preserve=(!readOk&&!missingConfirmed)||(exists&&(values.length>104||JSON.stringify(values[0]??[])!==JSON.stringify(columns)));
const rows=[];
if(!preserve&&exists)for(const valuesRow of values.slice(1)){
 const row=Object.fromEntries(fields.map((key,i)=>[key,valuesRow[i]??'']));
 if(!String(row.description).trim()){if(String(row.id).trim())preserve=true;continue;}
 rows.push({...row,id:String(row.id).trim()||undefined,version:Number(row.version),assetId:String(row.assetId).trim()||null,executedAt:String(row.executedAt).trim()||null,measurementDays:Number(row.measurementDays)});
}
if(rows.length>100)preserve=true;
return [{json:{spreadsheetId:'1zpXXHuQ152wSZXdHb0yFJPVcdQiGOHvz4Yhxrmjdo-o',rows:preserve?[]:rows,preserveActionPlan:preserve,actionExists:exists,initialValues:values,columns}}];

const workspace=$('Marketing · อ่าน SQL Workspace').first().json;
const metadata=$('Marketing · อ่านโครงสร้าง Workspace').first().json;
const prepared=$('Marketing · ตรวจช่องมนุษย์').first().json;
const imported=$('Marketing · นำเข้างาน CAS').first().json;
const latest=$input.first()?.json??{};const latestBody=latest.body??latest;
const latestValues=Array.isArray(latestBody.values)?latestBody.values:[];
const expected=['Performance Overview','Top Content','Opportunities','Content Performance','Campaign & Funnel','Action Plan','Data Notes'];
if(workspace.spreadsheetId!=='1zpXXHuQ152wSZXdHb0yFJPVcdQiGOHvz4Yhxrmjdo-o'||!Array.isArray(workspace.sheets)||JSON.stringify(workspace.sheets.map(x=>x.title))!==JSON.stringify(expected))throw new Error('MARKETING_WORKSPACE_INVALID');
const sameRows=JSON.stringify(prepared.initialValues)===JSON.stringify(latestValues);
const latestReadOk=Number(latest.statusCode??200)===200&&!latestBody.error;
const missingConfirmed=!prepared.actionExists&&[400,404].includes(Number(latest.statusCode))&&!!latestBody.error;
let preserve=prepared.preserveActionPlan||imported.preserveActionPlan!==false||imported.status!=='completed'||!sameRows||(!latestReadOk&&!missingConfirmed);
const actionSheet=workspace.sheets.find(x=>x.title==='Action Plan');
const actions=new Map(actionSheet.rows.filter(x=>x.id).map(x=>[x.id,x]));
for(const result of imported.results??[])if(result.id&&actions.has(result.id)&&actions.get(result.id).version!==result.version)preserve=true;
const sheets=new Map((metadata.sheets??[]).map(x=>[x.properties.title,x.properties]));
const used=new Set([...sheets.values()].map(x=>x.sheetId));
let nextId=91000;const requests=[];
const value=v=>v===null||v===undefined||v===''?{}:{userEnteredValue:typeof v==='number'&&Number.isFinite(v)?{numberValue:v}:typeof v==='boolean'?{boolValue:v}:{stringValue:String(v)}};
const row=(columns,data)=>({values:columns.map(column=>value(data[column]))});
for(const sheet of workspace.sheets){
 if(!Array.isArray(sheet.columns)||!sheet.columns.length||!Array.isArray(sheet.rows)||sheet.rows.length>5000)throw new Error('MARKETING_SHEET_INVALID');
 if(sheet.title==='Action Plan'&&preserve)continue;
 let properties=sheets.get(sheet.title);const exists=!!properties;
 if(!properties){while(used.has(nextId))nextId++;properties={sheetId:nextId++,title:sheet.title,gridProperties:{rowCount:Math.max(100,sheet.rows.length+1),columnCount:Math.max(26,sheet.columns.length)}};used.add(properties.sheetId);requests.push({addSheet:{properties}});}
 const id=properties.sheetId,grid=properties.gridProperties??{},rowCount=Math.max(grid.rowCount??100,sheet.rows.length+1),columnCount=Math.max(grid.columnCount??26,sheet.columns.length);
 requests.push({updateSheetProperties:{properties:{sheetId:id,gridProperties:{frozenRowCount:1,rowCount,columnCount}},fields:'gridProperties.frozenRowCount,gridProperties.rowCount,gridProperties.columnCount'}});
 if(sheet.title!=='Action Plan'||!exists){
  const rows=[{values:sheet.columns.map(v=>value(v))},...sheet.rows.map(data=>row(sheet.columns,data))];
  requests.push({updateCells:{range:{sheetId:id,startRowIndex:0,endRowIndex:rowCount,startColumnIndex:0,endColumnIndex:sheet.columns.length},rows,fields:'userEnteredValue'}});
 }else{
  const results=new Map((imported.results??[]).map(x=>[x.importKey,x]));const present=new Set();
  for(let index=1;index<latestValues.length;index++){
   const original=latestValues[index],key=String(original[14]??''),result=results.get(key),idValue=String(original[0]??'')||result?.id;
   if(!idValue)continue;present.add(idValue);const action=actions.get(idValue);if(!action)continue;
   if(!original[0]&&result?.id)requests.push({updateCells:{start:{sheetId:id,rowIndex:index,columnIndex:0},rows:[{values:[value(result.id)]}],fields:'userEnteredValue'}});
   requests.push({updateCells:{start:{sheetId:id,rowIndex:index,columnIndex:1},rows:[{values:[value(action.version)]}],fields:'userEnteredValue'}});
   requests.push({updateCells:{start:{sheetId:id,rowIndex:index,columnIndex:15},rows:[{values:sheet.columns.slice(15).map(column=>value(action[column]))}],fields:'userEnteredValue'}});
  }
  const append=sheet.rows.filter(data=>data.id&&!present.has(data.id));
  const blankExists=latestValues.slice(1).some(valuesRow=>!String(valuesRow[0]??'')&&!String(valuesRow[5]??'').trim());
  if(!blankExists)append.push(...sheet.rows.filter(data=>!data.id));
  if(append.length)requests.push({appendCells:{sheetId:id,rows:append.map(data=>row(sheet.columns,data)),fields:'userEnteredValue'}});
 }
 requests.push({repeatCell:{range:{sheetId:id,startRowIndex:0,endRowIndex:1},cell:{userEnteredFormat:{textFormat:{bold:true,foregroundColor:{red:1,green:1,blue:1}},backgroundColor:{red:.15,green:.09,blue:.09}}},fields:'userEnteredFormat.textFormat,userEnteredFormat.backgroundColor'}});
 requests.push({setBasicFilter:{filter:{range:{sheetId:id,startRowIndex:0,endRowIndex:sheet.title==='Action Plan'?rowCount:Math.max(1,sheet.rows.length+1),startColumnIndex:0,endColumnIndex:sheet.columns.length}}}});
 requests.push({updateDimensionProperties:{range:{sheetId:id,dimension:'COLUMNS',startIndex:0,endIndex:sheet.columns.length},properties:{pixelSize:180},fields:'pixelSize'}});
 requests.push({repeatCell:{range:{sheetId:id,startRowIndex:1,endRowIndex:rowCount,startColumnIndex:0,endColumnIndex:sheet.columns.length},cell:{userEnteredFormat:{wrapStrategy:'WRAP',verticalAlignment:'TOP'}},fields:'userEnteredFormat.wrapStrategy,userEnteredFormat.verticalAlignment'}});
 if(sheet.title==='Action Plan'){
  requests.push({repeatCell:{range:{sheetId:id,startRowIndex:0,endRowIndex:1,startColumnIndex:2,endColumnIndex:14},cell:{userEnteredFormat:{backgroundColor:{red:.37,green:.28,blue:.09}}},fields:'userEnteredFormat.backgroundColor'}});
  requests.push({updateDimensionProperties:{range:{sheetId:id,dimension:'COLUMNS',startIndex:5,endIndex:6},properties:{pixelSize:420},fields:'pixelSize'}});
  requests.push({updateDimensionProperties:{range:{sheetId:id,dimension:'COLUMNS',startIndex:11,endIndex:14},properties:{pixelSize:320},fields:'pixelSize'}});
 }
 if(sheet.title==='Action Plan')for(const[key,allowed]of[['priority',['high','medium','low']],['status',['backlog','planned','doing','measuring','done']],['actionType',['title','description','refresh','cta','internal_link','expansion','promotion','keyword','investigation']],['expectedMetric',['organic_sessions','search_clicks','line_clicks','calculator_complete','social_views']]])requests.push({setDataValidation:{range:{sheetId:id,startRowIndex:1,endRowIndex:rowCount,startColumnIndex:sheet.columns.indexOf(key),endColumnIndex:sheet.columns.indexOf(key)+1},rule:{condition:{type:'ONE_OF_LIST',values:allowed.map(userEnteredValue=>({userEnteredValue}))},strict:true,showCustomUi:true}}});
}
requests.unshift({updateSpreadsheetProperties:{properties:{timeZone:'Asia/Bangkok',locale:'th_TH'},fields:'timeZone,locale'}});
const batchBody={requests};if(JSON.stringify(batchBody).length>8000000)throw new Error('MARKETING_WORKSPACE_TOO_LARGE');
return [{json:{spreadsheetId:workspace.spreadsheetId,spreadsheetUrl:'https://docs.google.com/spreadsheets/d/'+workspace.spreadsheetId+'/edit',preserveActionPlan:!!preserve,analysisStatus:workspace.analysisStatus,sourceManifestCount:workspace.sourceManifest?.length??0,tabCount:7,batchBody}}];

